def funnel_material_mode_for_stage(_flow: SearchState, stage: str) -> str:
    """Explicit material-funnel command boundary and its downstream stage invocation. Implements `funnel_material_mode_for_stage` for this responsibility."""
    normalized = str(stage or '').strip().lower().replace('-', '_').replace(' ', '_')
    if normalized in {'global_develop', 'develop'}:
        normalized = 'develop'
    elif normalized == 'refine_scout':
        normalized = 'refine'
    return _flow.exploration.funnel_stage_material_modes.get(normalized, _flow.exploration.funnel_material_mode)

def funnel_stage_requests_real_glass(_flow: SearchState, stage: str) -> bool:
    """Explicit material-funnel command boundary and its downstream stage invocation. Implements `funnel_stage_requests_real_glass` for this responsibility."""
    return funnel_material_mode_for_stage(_flow, stage) in {'fixed', 'discrete'}

def prepare_de_dls_explore_context(_flow: SearchState, global_explore_dir: Path, stage_command: list[str]) -> Path:
    """Explicit material-funnel command boundary and its downstream stage invocation. Implements `prepare_de_dls_explore_context` for this responsibility."""
    context_dir = _flow.inputs.run_dir / '_prepared_de_dls_explore_context'
    context_dir.mkdir(parents=True, exist_ok=True)
    for name in ['basin_archive.json', 'basin_archive.csv', 'population.csv', 'population_scores.csv', 'adaptive_hybrid_trace.jsonl', 'hybrid_trace.jsonl']:
        source = global_explore_dir / name
        if source.exists():
            shutil.copyfile(source, context_dir / name)
    for source, target_name in [(_flow.optics.system_path, 'system_input.json'), (_flow.optics.variables_path, 'variables.json'), (_flow.optics.downstream_funnel_merit_path, 'merit.json'), (_flow.optics.glass_search_path, 'glass_search.json')]:
        if source.exists():
            shutil.copyfile(source, context_dir / target_name)
    reference_command = [str(item) for item in stage_command] if stage_command else []
    if '--aiming' not in reference_command:
        reference_command = [str(_flow.runtime.exe), '--system', str(context_dir / 'system_input.json'), '--merit', str(context_dir / 'merit.json'), '--variables', str(context_dir / 'variables.json'), '--aiming', _flow.settings.aiming_mode, '--aiming-iter', str(int(_flow.settings.options.get('aiming_iter', 20) or 20)), '--trace-policy', str(_flow.optics.downstream_funnel_merit.get('trace_policy', 'soft_coverage')), '--rays', str(int(_flow.optics.downstream_funnel_merit.get('num_rays', _flow.optics.search_merit['num_rays']))), '--arms', str(int(_flow.optics.downstream_funnel_merit.get('pupil_arms', _flow.optics.search_merit['pupil_arms']))), '--distribution', str(_flow.optics.downstream_funnel_merit.get('pupil_distribution', _flow.optics.search_merit['pupil_distribution'])), '--sampling-seed', str(int(_flow.optics.downstream_funnel_merit.get('sampling_seed', 1))), '--spot-rays', str(int(_flow.settings.options.get('spot_rays', 41))), '--spot-arms', str(int(_flow.settings.options.get('spot_arms', 64))), '--spot-distribution', str(_flow.settings.options.get('spot_distribution', 'uniform')), '--spot-sampling-seed', str(int(_flow.settings.options.get('spot_sampling_seed', _flow.optics.downstream_funnel_merit.get('sampling_seed', 1)))), '--local', '--local-bounds-mode', str(_flow.settings.options.get('initial_search_local_bounds_mode', 'safety')), '--local-residual-mode', str(_flow.settings.options.get('initial_search_local_residual_mode', 'expanded')), '--out-dir', str(global_explore_dir)]
        _lensde_materials.append_aiming_policy_args(reference_command, _flow.settings.options)
        if not _flow.runtime.use_cuda:
            reference_command.append('--cpu')
    if bool(_flow.settings.options.get('initial_search_funnel_global_near_trace_enabled', True)):
        if '--adaptive-allow-near-trace-infeasible' not in reference_command:
            reference_command.append('--adaptive-allow-near-trace-infeasible')
        if '--trace-coverage-epsilon' not in reference_command:
            minimum_coverage = min(1.0, max(0.0, _lensde_configuration.finite_float(_flow.settings.options.get('initial_search_funnel_global_near_trace_min_coverage'), 0.95)))
            reference_command.extend(['--trace-coverage-epsilon', f'{1.0 - minimum_coverage:.17g}'])
    for flag in ('--clear-aperture-update', '--sync-stop-aperture'):
        if flag not in reference_command:
            reference_command.append(flag)
    _lensde_provenance.write_json(context_dir / 'command.json', reference_command)
    _lensde_provenance.write_json(context_dir / 'run_meta.json', {'strategy': 'de_dls_material_funnel_context', 'source_stage': 'funnel_global_explore', 'source_stage_dir': str(global_explore_dir), 'command': reference_command, 'executable': str(_flow.runtime.exe)})
    return context_dir

def option_int_value(_flow: SearchState, key: str, default: int, minimum: int=0) -> int:
    """Explicit material-funnel command boundary and its downstream stage invocation. Implements `option_int_value` for this responsibility."""
    try:
        value = _flow.settings.options.get(key, default)
        if value is None or value == '':
            value = default
        return max(minimum, int(value))
    except (TypeError, ValueError):
        return max(minimum, int(default))

def option_float_value(_flow: SearchState, key: str, default: float, minimum: float=0.0) -> float:
    """Explicit material-funnel command boundary and its downstream stage invocation. Implements `option_float_value` for this responsibility."""
    try:
        value = _flow.settings.options.get(key, default)
        if value is None or value == '':
            value = default
        return max(minimum, float(value))
    except (TypeError, ValueError):
        return max(minimum, float(default))

def option_text_value(_flow: SearchState, key: str, default: str) -> str:
    """Explicit material-funnel command boundary and its downstream stage invocation. Implements `option_text_value` for this responsibility."""
    value = str(_flow.settings.options.get(key, default) or default).strip()
    return value or default

def option_choice_value(_flow: SearchState, key: str, choices: set[str], default: str) -> str:
    """Explicit material-funnel command boundary and its downstream stage invocation. Implements `option_choice_value` for this responsibility."""
    value = option_text_value(_flow, key, default)
    return value if value in choices else default

